(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit63-trap-c4-basic-1"]={"id":"unit63-trap-c4-basic-1","unitId":"6-3","chapterIds":["6-3"],"unitType":"basic","group":"6-3단원 · 선지 변형 유형 · 비교","name":"기본 OX 1","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit63","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"비교","parts":[{"name":"U63-H01-02-B1 · 만연의 뜻","items":[{"paragraphCount":1,"readingLabel":"1문단 · 핵심 읽기 2/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 1문단","passage":"[핵심 문장 · 1문단]\n국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"‘가독성’은 얼마나 쉽게 읽히는가이고, ‘만연’은 널리 퍼져 있다는 뜻이다.\n근거: “국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다.”","evidence":{"title":"만연의 뜻","statement":"‘가독성 영역에서의 피로가 만연해 있다’는 쉽게 읽히지 않아 생기는 피로가 널리 퍼져 있다는 뜻이다.","explanation":"‘가독성’은 얼마나 쉽게 읽히는가이고, ‘만연’은 널리 퍼져 있다는 뜻이다.\n근거: “국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다.”","valid":["T01:1"],"sources":[{"id":"T01","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"1문단","sentences":[{"id":"T01:1","text":"국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다.","paragraph":0,"memberIds":["T01:1"],"topic":"우리나라에서는 글자의 모양과 배치를 다듬는 일(타이포그래피)을 중요하게 여기지 않는다. 그래서 글이 잘 안 읽혀서(가독성이 낮아서) 생기는 피로가 곳곳에 널리 퍼져 있다(만연해 있다)."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T01:1","text":"국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H01-02-B1","type":"ox","answer":"O","changed":"‘가독성 영역에서의 피로가 만연해 있다’는 쉽게 읽히지 않아 생기는 피로가 널리 퍼져 있다는 뜻이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"만연의 뜻","hintGuide":"‘가독성’과 ‘만연’을 쉬운 말로 바꾸어 보세요.","synthesis":false,"editorSourceVersion":"a5fb6a272d061ef1c7a5cd4afba9f7af3b0ec0af88372cfe4a29523f0409e6c7"}]},{"name":"U63-E01-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"1문단 · 새 예시 적용","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 1문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 1문단]\n국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다. 의약 관련 제품이나 설명서의 경우, 글자조차 제대로 안 보일 정도로 눈을 위한 기본적인 배려가 갖춰져 있지 않다. 한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다. 당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서윤이가 체험학습 가정통신문을 받아 왔다. 긴 인사말과 학교 소개가 빽빽한데, 꼭 알아야 할 신청서 마감일과 준비물은 그 사이에 작은 글씨로 묻혀 있다. 서윤이도 한참을 들여다본 뒤에야 마감일과 준비물을 찾았다. 서윤이를 돌봐 주시는 할머니는 안경을 쓰고도 결국 찾지 못해, 신청서를 늦게 낼 뻔했다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"긴 인사말과 학교 소개는 큰 의미 없는 ‘시트르산 수화물’에, 신청서 마감일과 준비물은 뚜렷이 구분되어야 할 복용량과 주의 사항에 대응한다. 서윤이도 한참 찾고 할머니는 더 힘든 것은 젊은 시력으로도 한참 찾아야 하고 고령자는 더 큰 불편을 겪는 것과 같다.\n근거: “한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다.” “당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.”\n1문단에서 확인할 수 있어요.","evidence":{"title":"체험학습 가정통신문","statement":"마감일과 준비물은 복용량·주의 사항처럼 뚜렷해야 할 정보이다.","explanation":"긴 인사말과 학교 소개는 큰 의미 없는 ‘시트르산 수화물’에, 신청서 마감일과 준비물은 뚜렷이 구분되어야 할 복용량과 주의 사항에 대응한다. 서윤이도 한참 찾고 할머니는 더 힘든 것은 젊은 시력으로도 한참 찾아야 하고 고령자는 더 큰 불편을 겪는 것과 같다.\n근거: “한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다.” “당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.”\n1문단에서 확인할 수 있어요.","valid":["T01:3","T01:4"],"sources":[{"id":"T01","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"1문단","sentences":[{"id":"T01:1","text":"국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다.","paragraph":0,"memberIds":["T01:1"],"topic":"우리나라에서는 글자의 모양과 배치를 다듬는 일(타이포그래피)을 중요하게 여기지 않는다. 그래서 글이 잘 안 읽혀서(가독성이 낮아서) 생기는 피로가 곳곳에 널리 퍼져 있다(만연해 있다)."},{"id":"T01:2","text":"의약 관련 제품이나 설명서의 경우, 글자조차 제대로 안 보일 정도로 눈을 위한 기본적인 배려가 갖춰져 있지 않다.","paragraph":0,"memberIds":["T01:2"],"topic":"특히 약 상자나 약 설명서는 글자조차 제대로 안 보일 만큼, 읽는 사람의 눈을 생각한 기본적인 배려가 없다."},{"id":"T01:3","text":"한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다.","paragraph":0,"memberIds":["T01:3"],"topic":"어떤 약의 예를 보자. \"보통 어른은 한 번에 1병(100 ml)씩 하루 3번\"이라는 먹는 양(복용량)과 \"데워 마시되 전자레인지에 넣으면 위험하다\"라는 주의 사항은 꼭 알아야 할 정보다. 그러니 보통 사람에게는 별 의미가 없는 '시트르산 수화물'(약에 든 성분 이름)"},{"id":"T01:4","text":"당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.","paragraph":0,"memberIds":["T01:4"],"topic":"젊은 눈도 이렇게 힘드니, 눈이 나빠진 나이 많은 사람들(고령자)은 당연히 훨씬 더 불편할 수밖에 없다."}]}]},"examplePractice":true,"id":"U63-E01-B1","type":"ox","answer":"O","changed":"마감일과 준비물은 복용량·주의 사항처럼 뚜렷해야 할 정보이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"7efa8ebffb05f2f90fd2e23193c7ca281d68eef5a229bfd0b8f7973dcb96c40c"}]},{"name":"U63-E01-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"1문단 · 새 예시 적용","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 1문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 1문단]\n국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다. 의약 관련 제품이나 설명서의 경우, 글자조차 제대로 안 보일 정도로 눈을 위한 기본적인 배려가 갖춰져 있지 않다. 한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다. 당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서윤이가 체험학습 가정통신문을 받아 왔다. 긴 인사말과 학교 소개가 빽빽한데, 꼭 알아야 할 신청서 마감일과 준비물은 그 사이에 작은 글씨로 묻혀 있다. 서윤이도 한참을 들여다본 뒤에야 마감일과 준비물을 찾았다. 서윤이를 돌봐 주시는 할머니는 안경을 쓰고도 결국 찾지 못해, 신청서를 늦게 낼 뻔했다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"긴 인사말과 학교 소개는 큰 의미 없는 ‘시트르산 수화물’에, 신청서 마감일과 준비물은 뚜렷이 구분되어야 할 복용량과 주의 사항에 대응한다. 서윤이도 한참 찾고 할머니는 더 힘든 것은 젊은 시력으로도 한참 찾아야 하고 고령자는 더 큰 불편을 겪는 것과 같다.\n근거: “한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다.” “당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.”\n1문단에서 확인할 수 있어요.","evidence":{"title":"체험학습 가정통신문","statement":"마감일과 준비물은 복용량·주의 사항처럼 뚜렷해야 할 정보이다.","explanation":"긴 인사말과 학교 소개는 큰 의미 없는 ‘시트르산 수화물’에, 신청서 마감일과 준비물은 뚜렷이 구분되어야 할 복용량과 주의 사항에 대응한다. 서윤이도 한참 찾고 할머니는 더 힘든 것은 젊은 시력으로도 한참 찾아야 하고 고령자는 더 큰 불편을 겪는 것과 같다.\n근거: “한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다.” “당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.”\n1문단에서 확인할 수 있어요.","valid":["T01:3","T01:4"],"sources":[{"id":"T01","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"1문단","sentences":[{"id":"T01:1","text":"국내에서는 타이포그래피 분야에 대한 인식이 낮고, 특히 가독성 영역에서의 피로가 만연해 있다.","paragraph":0,"memberIds":["T01:1"],"topic":"우리나라에서는 글자의 모양과 배치를 다듬는 일(타이포그래피)을 중요하게 여기지 않는다. 그래서 글이 잘 안 읽혀서(가독성이 낮아서) 생기는 피로가 곳곳에 널리 퍼져 있다(만연해 있다)."},{"id":"T01:2","text":"의약 관련 제품이나 설명서의 경우, 글자조차 제대로 안 보일 정도로 눈을 위한 기본적인 배려가 갖춰져 있지 않다.","paragraph":0,"memberIds":["T01:2"],"topic":"특히 약 상자나 약 설명서는 글자조차 제대로 안 보일 만큼, 읽는 사람의 눈을 생각한 기본적인 배려가 없다."},{"id":"T01:3","text":"한 의약품의 예를 보면, “보통 성인 1회 1병(100 ml)을 1일 3회”라는 복용량과 “데워 마시되, 전자레인지에 넣으면 위험하다.”라는 내용은 일반 사용자에게는 큰 의미가 없을 ‘시트르산 수화물’과 같은 내용에 비해 뚜렷이 구분되어 전달되어야 하는데, 앞의 두 가지 정보를 알아내려면 젊은 시력으로도 불빛이 밝은 데 가서 시려 오는 눈을 비비며 한참을 찾아야 한다.","paragraph":0,"memberIds":["T01:3"],"topic":"어떤 약의 예를 보자. \"보통 어른은 한 번에 1병(100 ml)씩 하루 3번\"이라는 먹는 양(복용량)과 \"데워 마시되 전자레인지에 넣으면 위험하다\"라는 주의 사항은 꼭 알아야 할 정보다. 그러니 보통 사람에게는 별 의미가 없는 '시트르산 수화물'(약에 든 성분 이름)"},{"id":"T01:4","text":"당연히 시력이 안 좋은 고령자들은 더 큰 불편을 겪을 수밖에 없다.","paragraph":0,"memberIds":["T01:4"],"topic":"젊은 눈도 이렇게 힘드니, 눈이 나빠진 나이 많은 사람들(고령자)은 당연히 훨씬 더 불편할 수밖에 없다."}]}]},"examplePractice":true,"id":"U63-E01-B2","type":"ox","answer":"X","changed":"마감일과 준비물은 시트르산 수화물처럼 큰 의미 없는 정보이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":10,"end":29,"before":"시트르산 수화물처럼 큰 의미 없는 ","after":"복용량·주의 사항처럼 뚜렷해야 할 "}],"editorSourceVersion":"f9752ccad076a9dfc9bdec00ff46d1e97fb9a2ad51ef71f2c659d33eb17e3f1c"}]},{"name":"U63-E02-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"2문단 · 새 예시 적용","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 2문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 2문단]\n고령자를 위한 타이포그래피는 흔히 생각하듯 글자를 크게 하는 것만이 능사는 아니다. 나이가 들면 신체에 변화가 일어난다. 글자와 관련해서는 시력뿐 아니라 인지의 방식까지 달라진다. 어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다. 이것은 진화론적으로도 설명된다. 어린이들은 앞으로 펼쳐질 미래에 계속 새롭게 적응해 가야 하지만, 노인들은 지금까지 쌓아 온 경험과 지혜를 활용한다. 기술과 사회가 지금처럼 급변하지 않던 시대에 연령에 따라 인간이 적응해 온 방편이었을 것이다. 오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다. 성격이 완고해지는 듯 보이는 것도 이 때문이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n도윤이는 할머니와 햄버거 가게에 갔다. 주문은 점원 대신 터치 화면(키오스크)으로 해야 했다. 할머니는 한참 화면을 바라보다가 말로 주문하면 안 되느냐고 하셨다. 도윤이는 처음에 할머니가 고집을 부리신다고 생각했다. 하지만 할머니는 오랫동안 점원에게 말로 주문해 오셨고, 누를 때마다 화면이 바뀌는 새 방식이 낯설었을 뿐이었다. 도윤이는 할머니 옆에서 화면을 하나씩 천천히 짚어 드렸다. 할머니는 무사히 주문을 마치셨다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"오랫동안 해 온 말로 하는 주문은 고령자가 반응하는 고정된 것과 익숙함에, 누를 때마다 바뀌는 키오스크 화면은 시시각각 변하는 사회의 새로운 것에 대응한다. 고집처럼 보였지만 새 방식이 낯설었을 뿐인 것은 새로운 것에 적응하기 힘들어 완고해지는 듯 보이는 것과 같다.\n근거: “어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다.” “오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다.” “성격이 완고해지는 듯 보이는 것도 이 때문이다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"키오스크 앞의 할머니","statement":"할머니가 고집스러워 보인 것은 새 방식에 적응하기 힘들어서이다.","explanation":"오랫동안 해 온 말로 하는 주문은 고령자가 반응하는 고정된 것과 익숙함에, 누를 때마다 바뀌는 키오스크 화면은 시시각각 변하는 사회의 새로운 것에 대응한다. 고집처럼 보였지만 새 방식이 낯설었을 뿐인 것은 새로운 것에 적응하기 힘들어 완고해지는 듯 보이는 것과 같다.\n근거: “어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다.” “오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다.” “성격이 완고해지는 듯 보이는 것도 이 때문이다.”\n2문단에서 확인할 수 있어요.","valid":["T02:4","T02:8","T02:9"],"sources":[{"id":"T02","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"2문단","sentences":[{"id":"T02:1","text":"고령자를 위한 타이포그래피는 흔히 생각하듯 글자를 크게 하는 것만이 능사는 아니다.","paragraph":0,"memberIds":["T02:1"],"topic":"나이 많은 사람을 위한 글자 디자인이라고 하면 흔히 글자를 크게 하면 된다고 생각한다. 하지만 글자를 크게 하는 것'만'이 좋은 방법(능사)은 아니다."},{"id":"T02:2","text":"나이가 들면 신체에 변화가 일어난다.","paragraph":0,"memberIds":["T02:2"],"topic":"나이가 들면 몸에 변화가 생긴다."},{"id":"T02:3","text":"글자와 관련해서는 시력뿐 아니라 인지의 방식까지 달라진다.","paragraph":0,"memberIds":["T02:3"],"topic":"글자를 읽을 때는 눈이 잘 보이는 정도(시력)만 달라지는 것이 아니라, 무엇을 알아차리고 받아들이는 방식(인지 방식)까지 달라진다."},{"id":"T02:4","text":"어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다.","paragraph":0,"memberIds":["T02:4"],"topic":"어린이들은 움직이는 것과 새로운 것에 눈이 가지만, 고령자들은 멈춰 있는 것(고정된 것)과 익숙한 것에 눈이 간다."},{"id":"T02:5","text":"이것은 진화론적으로도 설명된다.","paragraph":0,"memberIds":["T02:5"],"topic":"이런 차이는 생물이 오랜 시간에 걸쳐 환경에 맞게 변해 왔다는 이론(진화론)으로도 설명할 수 있다."},{"id":"T02:6","text":"어린이들은 앞으로 펼쳐질 미래에 계속 새롭게 적응해 가야 하지만, 노인들은 지금까지 쌓아 온 경험과 지혜를 활용한다.","paragraph":0,"memberIds":["T02:6"],"topic":"어린이는 앞으로 다가올 미래에 계속 새롭게 적응해 가야 한다. 반면 노인은 지금까지 쌓아 온 경험과 지혜를 활용한다."},{"id":"T02:7","text":"기술과 사회가 지금처럼 급변하지 않던 시대에 연령에 따라 인간이 적응해 온 방편이었을 것이다.","paragraph":0,"memberIds":["T02:7"],"topic":"기술과 사회가 지금처럼 빠르게 바뀌지 않던 옛날에는, 이렇게 나이에 따라 다르게 반응하는 것이 사람이 적응해 온 방법(방편)이었을 것이다."},{"id":"T02:8","text":"오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다.","paragraph":0,"memberIds":["T02:8"],"topic":"오늘날처럼 순간순간(시시각각) 바뀌는 사회에서는 노인들이 새로운 것에 적응하기 힘들다. 우리는 이 사실을 이해해야 한다."},{"id":"T02:9","text":"성격이 완고해지는 듯 보이는 것도 이 때문이다.","paragraph":0,"memberIds":["T02:9"],"topic":"노인의 성격이 고집스러워지는(완고해지는) 것처럼 보이는 것도 이 때문이다."}]}]},"examplePractice":true,"id":"U63-E02-B1","type":"ox","answer":"O","changed":"할머니가 고집스러워 보인 것은 새 방식에 적응하기 힘들어서이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"e3cdaa850a12e8295581cd22a2ce1cf5ed1461a44bf194f2c34ca5f7a1cf8358"}]},{"name":"U63-E02-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"2문단 · 새 예시 적용","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 2문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 2문단]\n고령자를 위한 타이포그래피는 흔히 생각하듯 글자를 크게 하는 것만이 능사는 아니다. 나이가 들면 신체에 변화가 일어난다. 글자와 관련해서는 시력뿐 아니라 인지의 방식까지 달라진다. 어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다. 이것은 진화론적으로도 설명된다. 어린이들은 앞으로 펼쳐질 미래에 계속 새롭게 적응해 가야 하지만, 노인들은 지금까지 쌓아 온 경험과 지혜를 활용한다. 기술과 사회가 지금처럼 급변하지 않던 시대에 연령에 따라 인간이 적응해 온 방편이었을 것이다. 오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다. 성격이 완고해지는 듯 보이는 것도 이 때문이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n도윤이는 할머니와 햄버거 가게에 갔다. 주문은 점원 대신 터치 화면(키오스크)으로 해야 했다. 할머니는 한참 화면을 바라보다가 말로 주문하면 안 되느냐고 하셨다. 도윤이는 처음에 할머니가 고집을 부리신다고 생각했다. 하지만 할머니는 오랫동안 점원에게 말로 주문해 오셨고, 누를 때마다 화면이 바뀌는 새 방식이 낯설었을 뿐이었다. 도윤이는 할머니 옆에서 화면을 하나씩 천천히 짚어 드렸다. 할머니는 무사히 주문을 마치셨다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"오랫동안 해 온 말로 하는 주문은 고령자가 반응하는 고정된 것과 익숙함에, 누를 때마다 바뀌는 키오스크 화면은 시시각각 변하는 사회의 새로운 것에 대응한다. 고집처럼 보였지만 새 방식이 낯설었을 뿐인 것은 새로운 것에 적응하기 힘들어 완고해지는 듯 보이는 것과 같다.\n근거: “어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다.” “오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다.” “성격이 완고해지는 듯 보이는 것도 이 때문이다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"키오스크 앞의 할머니","statement":"할머니가 고집스러워 보인 것은 새 방식에 적응하기 힘들어서이다.","explanation":"오랫동안 해 온 말로 하는 주문은 고령자가 반응하는 고정된 것과 익숙함에, 누를 때마다 바뀌는 키오스크 화면은 시시각각 변하는 사회의 새로운 것에 대응한다. 고집처럼 보였지만 새 방식이 낯설었을 뿐인 것은 새로운 것에 적응하기 힘들어 완고해지는 듯 보이는 것과 같다.\n근거: “어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다.” “오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다.” “성격이 완고해지는 듯 보이는 것도 이 때문이다.”\n2문단에서 확인할 수 있어요.","valid":["T02:4","T02:8","T02:9"],"sources":[{"id":"T02","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"2문단","sentences":[{"id":"T02:1","text":"고령자를 위한 타이포그래피는 흔히 생각하듯 글자를 크게 하는 것만이 능사는 아니다.","paragraph":0,"memberIds":["T02:1"],"topic":"나이 많은 사람을 위한 글자 디자인이라고 하면 흔히 글자를 크게 하면 된다고 생각한다. 하지만 글자를 크게 하는 것'만'이 좋은 방법(능사)은 아니다."},{"id":"T02:2","text":"나이가 들면 신체에 변화가 일어난다.","paragraph":0,"memberIds":["T02:2"],"topic":"나이가 들면 몸에 변화가 생긴다."},{"id":"T02:3","text":"글자와 관련해서는 시력뿐 아니라 인지의 방식까지 달라진다.","paragraph":0,"memberIds":["T02:3"],"topic":"글자를 읽을 때는 눈이 잘 보이는 정도(시력)만 달라지는 것이 아니라, 무엇을 알아차리고 받아들이는 방식(인지 방식)까지 달라진다."},{"id":"T02:4","text":"어린이들이 움직이는 것과 새로운 것에 반응한다면, 고령자들은 고정된 것과 익숙함에 반응한다.","paragraph":0,"memberIds":["T02:4"],"topic":"어린이들은 움직이는 것과 새로운 것에 눈이 가지만, 고령자들은 멈춰 있는 것(고정된 것)과 익숙한 것에 눈이 간다."},{"id":"T02:5","text":"이것은 진화론적으로도 설명된다.","paragraph":0,"memberIds":["T02:5"],"topic":"이런 차이는 생물이 오랜 시간에 걸쳐 환경에 맞게 변해 왔다는 이론(진화론)으로도 설명할 수 있다."},{"id":"T02:6","text":"어린이들은 앞으로 펼쳐질 미래에 계속 새롭게 적응해 가야 하지만, 노인들은 지금까지 쌓아 온 경험과 지혜를 활용한다.","paragraph":0,"memberIds":["T02:6"],"topic":"어린이는 앞으로 다가올 미래에 계속 새롭게 적응해 가야 한다. 반면 노인은 지금까지 쌓아 온 경험과 지혜를 활용한다."},{"id":"T02:7","text":"기술과 사회가 지금처럼 급변하지 않던 시대에 연령에 따라 인간이 적응해 온 방편이었을 것이다.","paragraph":0,"memberIds":["T02:7"],"topic":"기술과 사회가 지금처럼 빠르게 바뀌지 않던 옛날에는, 이렇게 나이에 따라 다르게 반응하는 것이 사람이 적응해 온 방법(방편)이었을 것이다."},{"id":"T02:8","text":"오늘날처럼 시시각각 변하는 사회에서는 노인들이 새로운 것에 적응하기 힘들다는 사실을 이해해야 한다.","paragraph":0,"memberIds":["T02:8"],"topic":"오늘날처럼 순간순간(시시각각) 바뀌는 사회에서는 노인들이 새로운 것에 적응하기 힘들다. 우리는 이 사실을 이해해야 한다."},{"id":"T02:9","text":"성격이 완고해지는 듯 보이는 것도 이 때문이다.","paragraph":0,"memberIds":["T02:9"],"topic":"노인의 성격이 고집스러워지는(완고해지는) 것처럼 보이는 것도 이 때문이다."}]}]},"examplePractice":true,"id":"U63-E02-B2","type":"ox","answer":"X","changed":"할머니가 고집스러워 보인 것은 원래 성격이 완고해서이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":17,"end":31,"before":"원래 성격이 완고해서이다.","after":"새 방식에 적응하기 힘들어서이다."}],"editorSourceVersion":"2c1f1ee6ada8c03c7ef055dd6db67701f406b4ce5d14d83c22c88266a48c1a7b"}]},{"name":"U63-H04-02-B1 · 행갈이의 뜻","items":[{"paragraphCount":1,"readingLabel":"4문단 · 핵심 읽기 2/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 4문단","passage":"[핵심 문장 · 4문단]\n글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"행갈이는 줄을 바꾸는 것이다. 글자가 지나치게 크면 한 줄에 들어가는 글자가 적어 줄이 자주 바뀐다.\n근거: “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”","evidence":{"title":"행갈이의 뜻","statement":"‘행갈이’는 글의 줄이 바뀌는 것을 말한다.","explanation":"행갈이는 줄을 바꾸는 것이다. 글자가 지나치게 크면 한 줄에 들어가는 글자가 적어 줄이 자주 바뀐다.\n근거: “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”","valid":["T04:8"],"sources":[{"id":"T04","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"4문단","sentences":[{"id":"T04:8","text":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","paragraph":0,"memberIds":["T04:8"],"topic":"글자가 지나치게 커서 줄이 자주 바뀌면(행갈이가 잦으면), 도움이 되기는커녕 오히려 내용을 알아차리고 기억하는 데 크게 방해가 된다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T04:8","text":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H04-02-B1","type":"ox","answer":"O","changed":"‘행갈이’는 글의 줄이 바뀌는 것을 말한다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"행갈이의 뜻","hintGuide":"‘행’이 줄이라는 뜻임을 떠올려 보세요.","synthesis":false,"editorSourceVersion":"09c79566c97f0aafcbf8b9b315f68b507b3edf6d3c7cf0672d2306ef0c9a3384"}]},{"name":"U63-H05-02-B1 · 심미성의 뜻","items":[{"paragraphCount":1,"readingLabel":"5문단 · 핵심 읽기 2/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 5문단","passage":"[핵심 문장 · 5문단]\n디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"‘심미성’은 아름다움을 살피는 성질이다.\n근거: “디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.”","evidence":{"title":"심미성의 뜻","statement":"‘디자인의 심미성을 추구하는 잡지’는 디자인의 아름다움을 중요하게 여기는 잡지라는 뜻이다.","explanation":"‘심미성’은 아름다움을 살피는 성질이다.\n근거: “디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.”","valid":["T05:5"],"sources":[{"id":"T05","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"5문단","sentences":[{"id":"T05:5","text":"디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.","paragraph":0,"memberIds":["T05:5"],"topic":"보기 좋은 디자인(심미성)을 중요하게 여기는 잡지나, 한 면에 많은 정보를 담아 치열한 느낌을 주어야 하는 신문은 흰 공간을 다른 것보다 적게 두는 편이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T05:5","text":"디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H05-02-B1","type":"ox","answer":"O","changed":"‘디자인의 심미성을 추구하는 잡지’는 디자인의 아름다움을 중요하게 여기는 잡지라는 뜻이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"심미성의 뜻","hintGuide":"‘심미성’을 쉬운 말로 바꾸어 보세요.","synthesis":false,"editorSourceVersion":"452d3f4654175e88bb6ee434c709a74bec31044f2dc4b361cc8d0b2a2e8a9b15"}]},{"name":"U63-H05-04-B1 · 다만 앞뒤의 관계","items":[{"paragraphCount":1,"readingLabel":"5문단 · 핵심 읽기 4/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 5문단","passage":"[핵심 문장 · 5문단]\n흰 공간이 많은 것은 젊은 사람들의 독서에도 편안함을 준다. 다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"앞에서는 젊은 사람에게도 편안하다는 장점을, ‘다만’ 뒤에서는 세련되어 보이지 못한다는 단점을 말한다.\n근거: “흰 공간이 많은 것은 젊은 사람들의 독서에도 편안함을 준다.” “다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다.”","evidence":{"title":"다만 앞뒤의 관계","statement":"‘다만’ 앞에서는 흰 공간의 장점을, 뒤에서는 단점을 말한다.","explanation":"앞에서는 젊은 사람에게도 편안하다는 장점을, ‘다만’ 뒤에서는 세련되어 보이지 못한다는 단점을 말한다.\n근거: “흰 공간이 많은 것은 젊은 사람들의 독서에도 편안함을 준다.” “다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다.”","valid":["T05:3","T05:4"],"sources":[{"id":"T05","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"5문단","sentences":[{"id":"T05:3","text":"흰 공간이 많은 것은 젊은 사람들의 독서에도 편안함을 준다.","paragraph":0,"memberIds":["T05:3"],"topic":"흰 공간이 많으면 젊은 사람들도 글을 편하게 읽을 수 있다."},{"id":"T05:4","text":"다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다.","paragraph":0,"memberIds":["T05:4"],"topic":"다만 읽기는 편해도 글 전체가 듬성듬성 느슨해 보여서, 디자인이 멋있고 깔끔해(세련되어) 보이지 않는다는 단점이 있다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T05:3","text":"흰 공간이 많은 것은 젊은 사람들의 독서에도 편안함을 준다."},{"id":"T05:4","text":"다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H05-04-B1","type":"ox","answer":"O","changed":"‘다만’ 앞에서는 흰 공간의 장점을, 뒤에서는 단점을 말한다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"다만 앞뒤의 관계","hintGuide":"‘다만’ 앞뒤가 장점인지 단점인지 보세요.","synthesis":false,"editorSourceVersion":"2fdb2405ca0ea4737431e24cfcfc2481bec9c286e22049f12856ea28acd1357a"}]},{"name":"U63-H05-05-B1 · 5문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"5문단 · 핵심 읽기 5/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 5문단","passage":"[문단 전체 · 5문단]\n글자와 글줄, 텍스트 주위로 흰 공간을 넉넉하게 주어서 눈을 편안하게 하는 것도 도움이 된다. 이 흰 공간을 ‘화이트 스페이스’라고 한다. 흰 공간이 많은 것은 젊은 사람들의 독서에도 편안함을 준다. 다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다. 디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"5문단은 화이트 스페이스의 장점과 단점을 함께 다룬다.\n근거: “글자와 글줄, 텍스트 주위로 흰 공간을 넉넉하게 주어서 눈을 편안하게 하는 것도 도움이 된다.” “다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다.”","evidence":{"title":"5문단의 핵심","statement":"5문단은 흰 공간이 눈을 편안하게 하지만 짜임새가 느슨해 보이는 단점도 있다고 설명한다.","explanation":"5문단은 화이트 스페이스의 장점과 단점을 함께 다룬다.\n근거: “글자와 글줄, 텍스트 주위로 흰 공간을 넉넉하게 주어서 눈을 편안하게 하는 것도 도움이 된다.” “다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다.”","valid":["T05:1","T05:4"],"sources":[{"id":"T05","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"5문단","sentences":[{"id":"T05:1","text":"글자와 글줄, 텍스트 주위로 흰 공간을 넉넉하게 주어서 눈을 편안하게 하는 것도 도움이 된다.","paragraph":0,"memberIds":["T05:1"],"topic":"글자와 글자 사이, 줄과 줄 사이, 글 둘레에 빈 곳(흰 공간)을 넉넉하게 두어 눈을 편하게 해 주는 것도 도움이 된다."},{"id":"T05:2","text":"이 흰 공간을 ‘화이트 스페이스’라고 한다.","paragraph":0,"memberIds":["T05:2"],"topic":"이 빈 곳을 '화이트 스페이스'라고 한다."},{"id":"T05:3","text":"흰 공간이 많은 것은 젊은 사람들의 독서에도 편안함을 준다.","paragraph":0,"memberIds":["T05:3"],"topic":"흰 공간이 많으면 젊은 사람들도 글을 편하게 읽을 수 있다."},{"id":"T05:4","text":"다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다.","paragraph":0,"memberIds":["T05:4"],"topic":"다만 읽기는 편해도 글 전체가 듬성듬성 느슨해 보여서, 디자인이 멋있고 깔끔해(세련되어) 보이지 않는다는 단점이 있다."},{"id":"T05:5","text":"디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.","paragraph":0,"memberIds":["T05:5"],"topic":"보기 좋은 디자인(심미성)을 중요하게 여기는 잡지나, 한 면에 많은 정보를 담아 치열한 느낌을 주어야 하는 신문은 흰 공간을 다른 것보다 적게 두는 편이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T05:1","text":"글자와 글줄, 텍스트 주위로 흰 공간을 넉넉하게 주어서 눈을 편안하게 하는 것도 도움이 된다."},{"id":"T05:4","text":"다만 읽기는 편해도 전체적인 텍스트의 짜임새가 느슨해 보이는 터라 디자인이 세련되어 보이지 못한다는 단점이 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H05-05-B1","type":"ox","answer":"O","changed":"5문단은 흰 공간이 눈을 편안하게 하지만 짜임새가 느슨해 보이는 단점도 있다고 설명한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"5문단의 핵심","hintGuide":"5문단의 장점과 단점을 한 문장으로 묶어 보세요.","synthesis":true,"editorSourceVersion":"a94e1978dce0830ba8f426c99d328dd97da3304e8f64e236c4ef61ed961a6a93"}]},{"name":"U63-E03-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"3문단 · 새 예시 적용","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 3문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 3문단]\n글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다. 너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다. 다만 시력 저하가 오기 전의 젊은 눈이 잘 적응하는 긴 글의 평균 글자 크기보다는 다소 크기를 키우도록 주의할 필요는 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서준이는 조별 발표 화면을 만들었다. 처음에는 글자를 아주 작게 해서 한 장에 내용을 가득 넣었다. 그러자 교실 뒷자리에서는 하나도 보이지 않았다. 이번에는 글자를 아주 크게 했다. 그랬더니 한 장에 몇 낱말만 들어가 화면이 서른 장이 넘었고, 화면이 다그치는 것처럼 답답해 보였다. 결국 서준이는 교실 뒤에서도 잘 보이면서, 한 장에 꼭 필요한 내용이 들어가는 알맞은 크기를 찾았다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"화면 크기, 한 장에 넣을 내용, 글자 크기는 공간의 면적, 메시지의 양, 글자 크기의 함수 관계에, 너무 커서 다그치는 것처럼 보인 화면은 공격적인 인상에, 뒤에서도 보이면서 내용이 들어가는 크기는 적정한 선에 대응한다.\n근거: “글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다.” “너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다.”\n3문단에서 확인할 수 있어요.","evidence":{"title":"조별 발표 화면의 글자 크기","statement":"서준이가 찾은 크기는 화면과 내용의 양을 함께 생각한 적정한 선이다.","explanation":"화면 크기, 한 장에 넣을 내용, 글자 크기는 공간의 면적, 메시지의 양, 글자 크기의 함수 관계에, 너무 커서 다그치는 것처럼 보인 화면은 공격적인 인상에, 뒤에서도 보이면서 내용이 들어가는 크기는 적정한 선에 대응한다.\n근거: “글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다.” “너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다.”\n3문단에서 확인할 수 있어요.","valid":["T03:1","T03:2"],"sources":[{"id":"T03","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"3문단","sentences":[{"id":"T03:1","text":"글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다.","paragraph":0,"memberIds":["T03:1"],"topic":"글자는 클수록 좋다고 생각하기 쉽다. 하지만 종이(지면)나 화면의 넓이는 늘 정해져 있다. 그리고 글자 크기, 전하려는 말의 양, 공간의 넓이는 하나가 바뀌면 다른 것도 따라 바뀌는 관계(함수 관계)다. 그래서 글자 크기에는 언제나 알맞은 정도(적정한 선)가 있다."},{"id":"T03:2","text":"너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다.","paragraph":0,"memberIds":["T03:2"],"topic":"글자가 너무 크면 읽는 사람의 마음에 공격적인 느낌을 줄 수도 있다."},{"id":"T03:3","text":"다만 시력 저하가 오기 전의 젊은 눈이 잘 적응하는 긴 글의 평균 글자 크기보다는 다소 크기를 키우도록 주의할 필요는 있다.","paragraph":0,"memberIds":["T03:3"],"topic":"그래도 눈이 나빠지기 전의 젊은 눈에 맞춘 긴 글의 보통 글자 크기보다는 조금(다소) 더 크게 하도록 신경 쓸 필요는 있다."}]}]},"examplePractice":true,"id":"U63-E03-B1","type":"ox","answer":"O","changed":"서준이가 찾은 크기는 화면과 내용의 양을 함께 생각한 적정한 선이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"cf68bad41383d78ed864a48dc8a00491656914e621e5743ada935819b1c8bf17"}]},{"name":"U63-E03-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"3문단 · 새 예시 적용","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 3문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 3문단]\n글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다. 너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다. 다만 시력 저하가 오기 전의 젊은 눈이 잘 적응하는 긴 글의 평균 글자 크기보다는 다소 크기를 키우도록 주의할 필요는 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서준이는 조별 발표 화면을 만들었다. 처음에는 글자를 아주 작게 해서 한 장에 내용을 가득 넣었다. 그러자 교실 뒷자리에서는 하나도 보이지 않았다. 이번에는 글자를 아주 크게 했다. 그랬더니 한 장에 몇 낱말만 들어가 화면이 서른 장이 넘었고, 화면이 다그치는 것처럼 답답해 보였다. 결국 서준이는 교실 뒤에서도 잘 보이면서, 한 장에 꼭 필요한 내용이 들어가는 알맞은 크기를 찾았다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"화면 크기, 한 장에 넣을 내용, 글자 크기는 공간의 면적, 메시지의 양, 글자 크기의 함수 관계에, 너무 커서 다그치는 것처럼 보인 화면은 공격적인 인상에, 뒤에서도 보이면서 내용이 들어가는 크기는 적정한 선에 대응한다.\n근거: “글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다.” “너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다.”\n3문단에서 확인할 수 있어요.","evidence":{"title":"조별 발표 화면의 글자 크기","statement":"서준이가 찾은 크기는 화면과 내용의 양을 함께 생각한 적정한 선이다.","explanation":"화면 크기, 한 장에 넣을 내용, 글자 크기는 공간의 면적, 메시지의 양, 글자 크기의 함수 관계에, 너무 커서 다그치는 것처럼 보인 화면은 공격적인 인상에, 뒤에서도 보이면서 내용이 들어가는 크기는 적정한 선에 대응한다.\n근거: “글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다.” “너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다.”\n3문단에서 확인할 수 있어요.","valid":["T03:1","T03:2"],"sources":[{"id":"T03","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"3문단","sentences":[{"id":"T03:1","text":"글자 크기는 클수록 좋다고 생각하기 쉽지만, 지면이나 화면에는 늘 제한이 있고 글자의 크기, 전달하려는 단어 및 메시지의 양, 공간의 면적은 함수 관계를 이루기 때문에 항상 적정한 선이 있다.","paragraph":0,"memberIds":["T03:1"],"topic":"글자는 클수록 좋다고 생각하기 쉽다. 하지만 종이(지면)나 화면의 넓이는 늘 정해져 있다. 그리고 글자 크기, 전하려는 말의 양, 공간의 넓이는 하나가 바뀌면 다른 것도 따라 바뀌는 관계(함수 관계)다. 그래서 글자 크기에는 언제나 알맞은 정도(적정한 선)가 있다."},{"id":"T03:2","text":"너무 커지면 감정적으로도 공격적인 인상을 줄 수 있다.","paragraph":0,"memberIds":["T03:2"],"topic":"글자가 너무 크면 읽는 사람의 마음에 공격적인 느낌을 줄 수도 있다."},{"id":"T03:3","text":"다만 시력 저하가 오기 전의 젊은 눈이 잘 적응하는 긴 글의 평균 글자 크기보다는 다소 크기를 키우도록 주의할 필요는 있다.","paragraph":0,"memberIds":["T03:3"],"topic":"그래도 눈이 나빠지기 전의 젊은 눈에 맞춘 긴 글의 보통 글자 크기보다는 조금(다소) 더 크게 하도록 신경 쓸 필요는 있다."}]}]},"examplePractice":true,"id":"U63-E03-B2","type":"ox","answer":"X","changed":"서준이가 찾은 크기는 무조건 가장 큰 크기이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":12,"end":26,"before":"무조건 가장 큰 크기이다.","after":"화면과 내용의 양을 함께 생각한 적정한 선이다."}],"editorSourceVersion":"ec9c20f1ff4f56eb16cf45af82d38a0a41520c511295b202e83eda2edaa68fdc"}]},{"name":"U63-E04-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"4문단 · 새 예시 적용","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 4문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 4문단]\n인지 심리학자이며 시각 인식 전문가인 키스 레이너(Keith Rayner)의 시선 추적 연구를 활자 디자이너 소피 바이어(Sofie Beier)가 도해한 그림을 보자. 인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다. 이것을 ‘안구 도약 운동’이라고 한다. 젊은 독자와 70세 이상 독자는 안구 도약에 큰 차이를 보인다. 고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다. 그리고 다시 뒤로 돌아가는 역행이 자주 일어난다. 이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다. 글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n예린이는 할아버지 휴대폰의 글자를 가장 크게 바꿔 드렸다. 그러자 한 줄에 두세 낱말만 들어가 문자 한 통이 여러 줄로 자꾸 꺾였다. 할아버지는 줄이 바뀔 때마다 앞으로 돌아가 다시 읽으셨고, 끝까지 읽고 나서도 무슨 내용인지 헷갈려 하셨다. 예린이는 글자를 한 단계 줄여 드렸다. 한 줄에 뜻이 통하는 덩어리가 들어가자, 할아버지는 한 번에 읽어 내려가셨다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["비교"],"why":"자꾸 꺾이는 문자는 글자가 지나치게 커서 잦아진 행갈이에, 줄이 바뀔 때마다 앞으로 돌아가 다시 읽는 것은 고령자에게 자주 일어나는 역행에 대응한다. 한 줄에 뜻이 통하는 덩어리가 들어가자 한 번에 읽힌 것은 눈이 덩어리 단위로 도약하는 것과 같다.\n근거: “인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다.” “그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.” “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”\n4문단에서 확인할 수 있어요.","evidence":{"title":"할아버지 휴대폰의 큰 글자","statement":"할아버지가 힘들었던 것은 글자가 지나치게 커 행갈이가 잦아서이다.","explanation":"자꾸 꺾이는 문자는 글자가 지나치게 커서 잦아진 행갈이에, 줄이 바뀔 때마다 앞으로 돌아가 다시 읽는 것은 고령자에게 자주 일어나는 역행에 대응한다. 한 줄에 뜻이 통하는 덩어리가 들어가자 한 번에 읽힌 것은 눈이 덩어리 단위로 도약하는 것과 같다.\n근거: “인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다.” “그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.” “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”\n4문단에서 확인할 수 있어요.","valid":["T04:2","T04:6","T04:8"],"sources":[{"id":"T04","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"4문단","sentences":[{"id":"T04:1","text":"인지 심리학자이며 시각 인식 전문가인 키스 레이너(Keith Rayner)의 시선 추적 연구를 활자 디자이너 소피 바이어(Sofie Beier)가 도해한 그림을 보자.","paragraph":0,"memberIds":["T04:1"],"topic":"사람이 무엇을 어떻게 알아차리는지 연구하는 심리학자(인지 심리학자) 키스 레이너는, 글을 읽을 때 눈이 어디를 보는지 따라가며 기록하는 연구(시선 추적 연구)를 했다. 글자 디자이너 소피 바이어가 이 연구를 그림으로 풀어 그렸는데(도해했는데), 그 그림을 보자."},{"id":"T04:2","text":"인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다.","paragraph":0,"memberIds":["T04:2"],"topic":"사람의 눈은 글을 읽을 때 I, t, o, o, k처럼 한 글자씩 차례로 읽지 않는다. 몇 글자를 한 덩어리로 묶어 보고 다음 덩어리로 훌쩍 건너뛴다(도약한다)."},{"id":"T04:3","text":"이것을 ‘안구 도약 운동’이라고 한다.","paragraph":0,"memberIds":["T04:3"],"topic":"이렇게 눈이 덩어리 단위로 건너뛰는 움직임을 '안구 도약 운동'이라고 한다."},{"id":"T04:4","text":"젊은 독자와 70세 이상 독자는 안구 도약에 큰 차이를 보인다.","paragraph":0,"memberIds":["T04:4"],"topic":"젊은 사람과 70세가 넘은 사람은 눈이 건너뛰는 모습(안구 도약)이 크게 다르다."},{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.","paragraph":0,"memberIds":["T04:5"],"topic":"고령자는 한곳을 오래 바라보며 한 번에 많은 양을 읽는다. 그래서 눈이 한 번에 멀리 건너뛰는(도약 거리가 긴) 대신, 건너뛰는 횟수(운동량)는 적다."},{"id":"T04:6","text":"그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.","paragraph":0,"memberIds":["T04:6"],"topic":"또 읽던 곳에서 다시 뒤로 돌아가 읽는 일(역행)이 자주 생긴다."},{"id":"T04:7","text":"이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다.","paragraph":0,"memberIds":["T04:7"],"topic":"그래서 글자가 너무 커도 내용을 이해하는 데 방해가 된다(지장을 준다)."},{"id":"T04:8","text":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","paragraph":0,"memberIds":["T04:8"],"topic":"글자가 지나치게 커서 줄이 자주 바뀌면(행갈이가 잦으면), 도움이 되기는커녕 오히려 내용을 알아차리고 기억하는 데 크게 방해가 된다."}]}]},"examplePractice":true,"id":"U63-E04-B1","type":"ox","answer":"O","changed":"할아버지가 힘들었던 것은 글자가 지나치게 커 행갈이가 잦아서이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"da4ffce89bb5b0271ed92bf49663160e80f14069166f0219edec19f45c87a4a3"}]}]};})(window);
